$(() => {
  const loadedAt = performance.now();
  const STYLE_ID = 'th-same-layer-visibility-style';
  const HOST_FLOOR_CLASS = 'th-same-layer-host';

  let initialLoadCompleted = false;
  let initialLoadTimer: ReturnType<typeof setTimeout> | null = null;
  let initialLoadListener: EventOnReturn | null = null;
  let syncTimer: ReturnType<typeof setTimeout> | null = null;
  let visibilityGuardTimer: ReturnType<typeof setInterval> | null = null;
  let chatObserver: MutationObserver | null = null;
  let isGenerating = false;

  const hostDocument = window.parent?.document ?? document;
  const hostWindow = hostDocument.defaultView ?? window;

  function getHostChat(): HTMLElement | null {
    return hostDocument.querySelector<HTMLElement>('#chat');
  }

  function getFloors(): JQuery<HTMLElement> {
    const chat = getHostChat();
    return chat ? $(chat).children<HTMLElement>('.mes') : $<HTMLElement>();
  }

  function readFloorStatus() {
    const floors = getFloors();
    const nonZeroFloors = floors.not('[mesid="0"]');
    const visibleNonZeroFloors = nonZeroFloors.filter((_index, element) => {
      const style = hostWindow.getComputedStyle(element);
      return style.display !== 'none' && style.visibility !== 'hidden';
    }).length;

    return {
      totalFloors: floors.length,
      nonZeroFloors: nonZeroFloors.length,
      visibleNonZeroFloors,
      elapsedMs: Math.round(performance.now() - loadedAt),
      initialLoadCompleted,
      isGenerating,
      hostChatFound: Boolean(getHostChat()),
      iframeChatFound: Boolean(document.querySelector('#chat')),
    };
  }

  function readAutocompleteStatus() {
    const activeElement = hostDocument.activeElement instanceof HTMLElement ? hostDocument.activeElement : null;
    const floatingLayers = $(hostDocument).find(
      '.autocomplete, .autoComplete, .autocomplete-menu, .floating-ui-root, .floating-container',
    );
    const visibleInputs = $(hostDocument)
      .find<HTMLElement>('textarea, input[type="text"], [contenteditable="true"]')
      .filter((_index, element) => {
        const style = hostWindow.getComputedStyle(element);
        return style.display !== 'none' && style.visibility !== 'hidden';
      });
    const describeElement = (element: HTMLElement) =>
      `${element.tagName.toLowerCase()}#${element.id || 'no-id'}.${element.className || 'no-class'}`;

    return {
      activeTag: activeElement?.tagName ?? null,
      activeId: activeElement?.id ?? null,
      activeClass: activeElement?.className ?? null,
      activeMesId: activeElement?.closest('.mes')?.getAttribute('mesid') ?? null,
      visibleInputCount: visibleInputs.length,
      visibleInputPreview: visibleInputs
        .map((_index, element) => describeElement(element))
        .get()
        .slice(0, 6),
      floatingLayerCount: floatingLayers.length,
      floatingLayerPreview: floatingLayers
        .map((_index, element) => (element instanceof HTMLElement ? describeElement(element) : 'unknown'))
        .get()
        .slice(0, 6),
      hostChatFound: Boolean(getHostChat()),
      iframeChatFound: Boolean(document.querySelector('#chat')),
    };
  }

  function logStatus(message: string, extra: Record<string, unknown> = {}) {
    console.info(`[苏北乡村·同层] ${message}`, { ...readFloorStatus(), ...extra });
  }

  function ensureVisibilityStyle() {
    const css = `
      #chat > .mes[mesid="0"] .mes_text:not(.th-native-editing),
      #chat > .mes.${HOST_FLOOR_CLASS} .mes_text:not(.th-native-editing) {
        display: none !important;
      }
      #chat > .mes:not([mesid="0"]):not(.${HOST_FLOOR_CLASS}) {
        display: none !important;
      }
    `;
    const style = hostDocument.getElementById(STYLE_ID);
    if (style) {
      // #chat 可能被酒馆重新构造；样式不能依赖挂在旧 #chat 上的临时属性。
      if (style.textContent !== css) style.textContent = css;
      return;
    }
    $('<style>').attr('id', STYLE_ID).text(css).appendTo(hostDocument.head);
  }

  function enforceNativeFloorVisibility(): number {
    ensureVisibilityStyle();
    const hostFloors = getFloors().filter(`[mesid="0"], .${HOST_FLOOR_CLASS}`);
    hostFloors.each((_index, element) => {
      element.style.removeProperty('display');
    });
    const hostFloorTexts = hostFloors.find<HTMLElement>('.mes_text');
    hostFloorTexts.each((_index, element) => {
      const isEditing = element.querySelector('#curEditTextarea') !== null;
      element.classList.toggle('th-native-editing', isEditing);
      if (isEditing) element.style.removeProperty('display');
      else element.style.setProperty('display', 'none', 'important');
    });
    const floors = getFloors().not(`[mesid="0"], .${HOST_FLOOR_CLASS}`);
    // 节点来自父窗口，直接写入 important，避免酒馆流式更新重新覆盖 display。
    floors.each((_index, element) => element.style.setProperty('display', 'none', 'important'));
    return floors.length;
  }

  function hideSubsequentFloors(reason: string) {
    const hiddenCount = enforceNativeFloorVisibility();
    if (hiddenCount === 0) return;

    console.info(`[苏北乡村·同层] ${reason}：已隐藏 ${hiddenCount} 个非第 0 层楼层`);
    logStatus('hideSubsequentFloors:after_hide', { reason, hiddenCount });
  }

  function syncFloorState(reason: string, { forceRemove = false }: { forceRemove?: boolean } = {}) {
    logStatus('syncFloorState:before', { reason, forceRemove });
    ensureVisibilityStyle();
    hideSubsequentFloors(reason);

    if (!initialLoadCompleted) {
      logStatus('syncFloorState:skip_remove_before_initial_load', { reason, forceRemove });
      return;
    }
    if (isGenerating && !forceRemove) {
      logStatus('syncFloorState:keep_hidden_during_generation', { reason, forceRemove });
      return;
    }
    // 不删除酒馆原生楼层。自动补全、编辑器和流式处理仍会引用其中的 DOM 节点；删除会让这些引用失效。
    logStatus('syncFloorState:keep_hidden_dom', { reason, forceRemove });
  }

  function scheduleSync(reason: string, delay = 50, forceRemove = false) {
    if (syncTimer !== null) window.clearTimeout(syncTimer);
    syncTimer = window.setTimeout(() => {
      syncTimer = null;
      syncFloorState(reason, { forceRemove });
    }, delay);
  }

  function unlockGeneration(source: string) {
    const wasGenerating = isGenerating;
    isGenerating = false;
    if (wasGenerating) {
      console.info(`[苏北乡村·同层] 退出生成锁定态，触发源：${source}`, {
        autocomplete: readAutocompleteStatus(),
      });
    }
    scheduleSync(`${source}:unlock_cleanup`, 80, true);
  }

  function registerChatObserver() {
    if (chatObserver) return;
    const root = hostDocument.documentElement;
    const floorSelector = `#chat > .mes:not([mesid="0"]):not(.${HOST_FLOOR_CLASS})`;

    chatObserver = new hostWindow.MutationObserver(mutations => {
      const floorAdded = mutations.some(mutation =>
        [...mutation.addedNodes].some(node => {
          // 父页面节点不能用子 iframe 的 HTMLElement 做 instanceof 判断。
          if (node.nodeType !== hostWindow.Node.ELEMENT_NODE) return false;
          const element = node as Element;
          return element.matches(floorSelector) || element.querySelector(floorSelector) !== null;
        }),
      );
      const styleRemoved = !hostDocument.getElementById(STYLE_ID);
      if (floorAdded || styleRemoved) syncFloorState(styleRemoved ? 'visibility_style_removed' : 'chat_mutation');
    });
    // 观察父页面根节点，即使酒馆替换整个 #chat，也能继续接管新楼层。
    chatObserver.observe(root, { childList: true, subtree: true });
    console.info('[苏北乡村·同层] 已注册父页面 MutationObserver', { autocomplete: readAutocompleteStatus() });
  }

  function finishInitialLoad(source: 'generate_after_data' | 'timeout') {
    if (initialLoadCompleted) return;
    initialLoadCompleted = true;
    initialLoadListener?.stop();
    initialLoadListener = null;
    if (initialLoadTimer !== null) {
      window.clearTimeout(initialLoadTimer);
      initialLoadTimer = null;
    }

    if (source === 'generate_after_data') {
      console.info('[苏北乡村·同层] 已在 generate_after_data 之后完成首次初始化');
    } else {
      console.warn('[苏北乡村·同层] 等待 generate_after_data 超时，使用 1000ms 兜底完成首次初始化');
    }
    logStatus('finishInitialLoad:before_cleanup', { source });
    registerChatObserver();
    syncFloorState(`initial_load:${source}`, { forceRemove: !isGenerating });
  }

  console.info('[苏北乡村·同层] 脚本已加载');
  ensureVisibilityStyle();
  logStatus('startup:before_first_hide');
  hideSubsequentFloors('startup');
  // 尽早接管后续楼层，避免初始化等待期间新插入的正文短暂出现在前端外部。
  registerChatObserver();
  // 酒馆的流式路径会跳过普通消息渲染事件；低频守卫作为 DOM 观察器之外的最终兜底。
  visibilityGuardTimer = window.setInterval(enforceNativeFloorVisibility, 250);

  console.info('[苏北乡村·同层] 首次初始化等待 generate_after_data，兜底 1000ms');
  initialLoadListener = eventOnce(tavern_events.GENERATE_AFTER_DATA, () => finishInitialLoad('generate_after_data'));
  initialLoadTimer = window.setTimeout(() => finishInitialLoad('timeout'), 1000);

  eventOn(tavern_events.GENERATION_STARTED, (_type, _options, dryRun) => {
    if (dryRun) return;
    const source = 'GENERATION_STARTED';
    if (!isGenerating) {
      console.info(`[苏北乡村·同层] 进入生成锁定态，触发源：${source}`, {
        autocomplete: readAutocompleteStatus(),
      });
    }
    isGenerating = true;
    syncFloorState(`${source}:lock`);
  });
  eventMakeFirst(tavern_events.CHARACTER_MESSAGE_RENDERED, messageId => {
    if (messageId !== 0) syncFloorState(`CHARACTER_MESSAGE_RENDERED:${messageId}`);
  });
  eventMakeFirst(tavern_events.STREAM_TOKEN_RECEIVED, () => enforceNativeFloorVisibility());
  eventMakeFirst(tavern_events.USER_MESSAGE_RENDERED, messageId => {
    if (messageId !== 0) enforceNativeFloorVisibility();
  });
  eventOn(tavern_events.MESSAGE_SENT, messageId => syncFloorState(`MESSAGE_SENT:${messageId}`));
  eventOn(tavern_events.MESSAGE_RECEIVED, (messageId, type) => syncFloorState(`MESSAGE_RECEIVED:${messageId}:${type}`));
  eventOn(tavern_events.MESSAGE_DELETED, messageId => scheduleSync(`MESSAGE_DELETED:${messageId}`, 0, true));
  eventOn(tavern_events.GENERATION_STOPPED, () => unlockGeneration('GENERATION_STOPPED'));
  eventOn(tavern_events.GENERATION_ENDED, messageId => unlockGeneration(`GENERATION_ENDED:${messageId}`));

  let currentChatId = SillyTavern.getCurrentChatId();
  eventOn(tavern_events.CHAT_CHANGED, chatId => {
    if (currentChatId === chatId) return;
    currentChatId = chatId;
    window.location.reload();
  });

  $(window).on('pagehide', () => {
    if (syncTimer !== null) window.clearTimeout(syncTimer);
    if (initialLoadTimer !== null) window.clearTimeout(initialLoadTimer);
    if (visibilityGuardTimer !== null) window.clearInterval(visibilityGuardTimer);
    initialLoadListener?.stop();
    chatObserver?.disconnect();
    syncTimer = null;
    initialLoadTimer = null;
    visibilityGuardTimer = null;
    initialLoadListener = null;
    chatObserver = null;
    getFloors()
      .filter(`[mesid="0"], .${HOST_FLOOR_CLASS}`)
      .find<HTMLElement>('.mes_text')
      .each((_index, element) => {
        element.classList.remove('th-native-editing');
        element.style.removeProperty('display');
      });
    getFloors()
      .filter(`.${HOST_FLOOR_CLASS}`)
      .each((_index, element) => {
        element.classList.remove(HOST_FLOOR_CLASS);
        element.style.removeProperty('display');
      });
    hostDocument.getElementById(STYLE_ID)?.remove();
  });

  console.info('[苏北乡村·同层] 楼层隐藏机制已启动');
});
